-- MasterApp Phase 21: partner platform, app marketplace, OAuth PKCE and safe extensions.
begin;

alter table public.plans
  add column if not exists partner_platform_enabled boolean not null default false,
  add column if not exists app_marketplace_enabled boolean not null default false,
  add column if not exists oauth_apps_enabled boolean not null default false,
  add column if not exists paid_apps_enabled boolean not null default false,
  add column if not exists max_app_installations integer;
alter table public.store_feature_flags
  add column if not exists partner_platform_enabled boolean not null default true,
  add column if not exists app_marketplace_enabled boolean not null default true,
  add column if not exists oauth_apps_enabled boolean not null default true,
  add column if not exists paid_apps_enabled boolean not null default false;

create table public.partner_accounts(
 id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,
 name text not null check(length(btrim(name)) between 2 and 120),company_name text not null check(length(btrim(company_name)) between 2 and 160),contact_email text not null,contact_phone text,
 status text not null default 'pending' check(status in('pending','active','suspended','rejected')),terms_accepted_at timestamptz not null,terms_version text not null default '2026-10',reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,rejection_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.app_categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text,sort_order integer not null default 100,active boolean not null default true,created_at timestamptz not null default now());
insert into public.app_categories(slug,name,sort_order) values ('orders','Pedidos',10),('delivery','Delivery',20),('finance','Financeiro',30),('fiscal','Fiscal',40),('marketing','Marketing',50),('crm','CRM',60),('inventory','Estoque',70),('analytics','Analytics',80),('other','Outros',90) on conflict(slug)do nothing;

create table public.partner_apps(
 id uuid primary key default gen_random_uuid(),partner_id uuid not null references public.partner_accounts(id) on delete cascade,category_id uuid references public.app_categories(id) on delete set null,
 client_id text not null unique check(client_id~'^app_[A-Za-z0-9]{24,64}$'),name text not null check(length(btrim(name)) between 2 and 100),slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),description text not null,short_description text not null check(length(short_description)<=180),logo_url text,website_url text,privacy_policy_url text not null check(privacy_policy_url~'^https://'),terms_url text not null check(terms_url~'^https://'),support_url text not null check(support_url~'^https://'),
 redirect_uris text[] not null default '{}',webhook_secret_vault_id uuid,webhook_secret_prefix text,status text not null default 'draft' check(status in('draft','submitted','under_review','approved','published','suspended','rejected','archived')),visibility text not null default 'public' check(visibility in('public','private','unlisted')),private_organization_id uuid references public.organizations(id) on delete cascade,pricing_type text not null default 'free' check(pricing_type in('free','paid','external_billing','revenue_share')),config_schema jsonb not null default '{"fields":[]}',verified boolean not null default false,kill_switch_active boolean not null default false,published_at timestamptz,suspended_at timestamptz,last_review_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(visibility<>'private' or private_organization_id is not null));
create table public.app_versions(
 id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete cascade,version text not null check(version~'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-[0-9A-Za-z.-]+)?$'),requested_scopes text[] not null default '{}',restricted_scopes text[] not null default '{}',webhook_url text check(webhook_url is null or webhook_url~'^https://'),webhook_events text[] not null default '{}',changelog text not null,status text not null default 'draft' check(status in('draft','submitted','under_review','approved','published','rejected','archived')),submitted_at timestamptz,approved_at timestamptz,approved_by uuid references auth.users(id) on delete set null,rejection_reason text,created_at timestamptz not null default now(),unique(app_id,version));
create table public.app_scopes(scope text primary key,display_name text not null,description text not null,sensitivity text not null default 'standard' check(sensitivity in('standard','restricted')),active boolean not null default true);
insert into public.app_scopes(scope,display_name,description,sensitivity) values
('orders:read','Ler pedidos','Consultar pedidos autorizados','standard'),('orders:write','Gerenciar pedidos','Criar e atualizar pedidos','restricted'),('products:read','Ler produtos','Consultar catálogo','standard'),('products:write','Atualizar produtos','Atualizar disponibilidade','restricted'),('customers:read','Ler clientes','Consultar dados mínimos do cliente','restricted'),('customers:export','Exportar clientes','Exportação controlada e assíncrona','restricted'),('inventory:read','Ler estoque','Consultar saldos','standard'),('inventory:write','Atualizar estoque','Movimentar estoque','restricted'),('reservations:read','Ler reservas','Consultar reservas','standard'),('reservations:write','Gerenciar reservas','Criar e atualizar reservas','restricted'),('finance:read','Ler financeiro','Consultar resumo financeiro','restricted'),('webhooks:manage','Gerenciar webhooks','Configurar eventos do app','restricted') on conflict(scope)do update set display_name=excluded.display_name,description=excluded.description,sensitivity=excluded.sensitivity;

create table public.app_installations(
 id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete restrict,app_version_id uuid not null references public.app_versions(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete cascade,all_stores boolean not null default false,installed_by_user_id uuid not null references auth.users(id) on delete restrict,granted_scopes text[] not null default '{}',consent_snapshot jsonb not null,consented_at timestamptz not null,status text not null default 'active' check(status in('requested','active','suspended','revoked')),vault_config_secret_id uuid,installed_at timestamptz not null default now(),revoked_at timestamptz,revoked_by uuid references auth.users(id) on delete set null,revocation_reason text,last_access_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index app_installations_active_unique on public.app_installations(app_id,organization_id) where status in('requested','active','suspended');
create table public.app_installation_stores(installation_id uuid not null references public.app_installations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,primary key(installation_id,store_id));
create table public.app_pricing(id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete cascade,pricing_type text not null check(pricing_type in('free','paid','external_billing','revenue_share')),price_cents integer check(price_cents>=0),billing_interval text check(billing_interval in('monthly','annual','one_time')),revenue_share_percentage numeric(5,2) check(revenue_share_percentage between 0 and 100),currency text not null default 'BRL',active boolean not null default true,created_at timestamptz not null default now());

create table public.app_oauth_authorizations(
 id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,redirect_uri text not null,state_value text not null,code_challenge text not null check(length(code_challenge) between 43 and 128),code_challenge_method text not null default 'S256' check(code_challenge_method='S256'),requested_scopes text[] not null,requested_store_ids uuid[] not null default '{}',authorization_code_hash text not null unique,approved boolean not null default false,used_at timestamptz,expires_at timestamptz not null default(now()+interval '10 minutes'),created_at timestamptz not null default now());
create table public.app_oauth_tokens(
 id uuid primary key default gen_random_uuid(),installation_id uuid not null references public.app_installations(id) on delete cascade,app_id uuid not null references public.partner_apps(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,access_token_hash text not null unique,refresh_token_hash text not null unique,scopes text[] not null,access_expires_at timestamptz not null,refresh_expires_at timestamptz not null,status text not null default 'active' check(status in('active','revoked','expired')),rotated_at timestamptz,last_used_at timestamptz,created_at timestamptz not null default now(),revoked_at timestamptz);
create table public.app_rate_limit_buckets(app_id uuid not null references public.partner_apps(id) on delete cascade,installation_id uuid not null references public.app_installations(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,bucket_start timestamptz not null,request_count integer not null default 0,primary key(app_id,installation_id,organization_id,bucket_start));
create table public.app_webhooks(id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete cascade,installation_id uuid not null references public.app_installations(id) on delete cascade,endpoint_id uuid not null unique references public.webhook_endpoints(id) on delete cascade,created_at timestamptz not null default now());

create table public.app_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,app_id uuid not null references public.partner_apps(id) on delete cascade,rating integer not null check(rating between 1 and 5),comment text check(length(comment)<=2000),created_by uuid not null references auth.users(id) on delete restrict,status text not null default 'published' check(status in('published','hidden','removed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,app_id));
create table public.app_review_reports(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.app_reviews(id) on delete cascade,reported_by uuid not null references auth.users(id) on delete cascade,reason text not null,status text not null default 'open' check(status in('open','reviewed','dismissed','actioned')),created_at timestamptz not null default now());
create table public.app_security_incidents(id uuid primary key default gen_random_uuid(),app_id uuid not null references public.partner_apps(id) on delete cascade,reason text not null,action text not null,status text not null default 'open' check(status in('open','contained','resolved')),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.app_audit_logs(id uuid primary key default gen_random_uuid(),app_id uuid references public.partner_apps(id) on delete set null,partner_id uuid references public.partner_accounts(id) on delete set null,installation_id uuid references public.app_installations(id) on delete set null,organization_id uuid references public.organizations(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,message text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());

alter table public.api_request_logs add column if not exists partner_app_id uuid references public.partner_apps(id) on delete set null,add column if not exists app_installation_id uuid references public.app_installations(id) on delete set null;
alter table public.api_idempotency_keys add column if not exists app_installation_id uuid references public.app_installations(id) on delete cascade;
alter table public.api_idempotency_keys alter column api_client_id drop not null;
alter table public.api_idempotency_keys add constraint api_idempotency_actor_check check((api_client_id is not null)<>(app_installation_id is not null));
create unique index api_idempotency_installation_key on public.api_idempotency_keys(app_installation_id,idempotency_key) where app_installation_id is not null;

create index partner_apps_marketplace_idx on public.partner_apps(status,visibility,category_id,published_at desc);
create index app_versions_review_idx on public.app_versions(status,submitted_at);
create index app_installations_org_idx on public.app_installations(organization_id,status,installed_at desc);
create index app_installations_app_idx on public.app_installations(app_id,status);
create index app_tokens_access_idx on public.app_oauth_tokens(access_token_hash,status,access_expires_at);
create index app_tokens_refresh_idx on public.app_oauth_tokens(refresh_token_hash,status,refresh_expires_at);
create index app_reviews_app_idx on public.app_reviews(app_id,status,created_at desc);
create index app_audit_app_idx on public.app_audit_logs(app_id,created_at desc);

create trigger partner_accounts_touch before update on public.partner_accounts for each row execute function public.touch_updated_at();
create trigger partner_apps_touch before update on public.partner_apps for each row execute function public.touch_updated_at();
create trigger app_installations_touch before update on public.app_installations for each row execute function public.touch_updated_at();
create trigger app_reviews_touch before update on public.app_reviews for each row execute function public.touch_updated_at();

create or replace function private.partner_owner(target_partner uuid) returns boolean language sql stable security definer set search_path='' as $$select private.is_superadmin() or exists(select 1 from public.partner_accounts p where p.id=target_partner and p.user_id=(select auth.uid()))$$;
revoke all on function private.partner_owner(uuid) from public,anon,authenticated;grant execute on function private.partner_owner(uuid) to authenticated;

create or replace function public.set_app_installation_config(requested_installation_id uuid,requested_config text) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;select vault_config_secret_id into sid from public.app_installations where id=requested_installation_id for update;if not found then raise exception 'Instalação não encontrada.';end if;if sid is null then select vault.create_secret(requested_config,'masterapp-app-installation-'||requested_installation_id::text,'Encrypted partner app configuration')into sid;else perform vault.update_secret(sid,requested_config,null,'Encrypted partner app configuration');end if;update public.app_installations set vault_config_secret_id=sid where id=requested_installation_id;return sid;end$$;
create or replace function public.set_partner_app_webhook_secret(requested_app_id uuid,requested_secret text) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' or length(requested_secret)<32 then raise exception 'Operação interna.';end if;select webhook_secret_vault_id into sid from public.partner_apps where id=requested_app_id for update;if not found then raise exception 'App não encontrado.';end if;if sid is null then select vault.create_secret(requested_secret,'masterapp-partner-app-'||requested_app_id::text,'Partner app webhook secret')into sid;else perform vault.update_secret(sid,requested_secret,null,'Partner app webhook secret');end if;update public.partner_apps set webhook_secret_vault_id=sid,webhook_secret_prefix=left(requested_secret,12)where id=requested_app_id;return sid;end$$;
create or replace function public.create_app_installation_webhook(requested_installation_id uuid,requested_url text,requested_events text[])returns uuid language plpgsql security definer set search_path='' as $$declare app_record record;endpoint uuid;raw_secret text;sid uuid;begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;select i.app_id,i.organization_id,a.name,a.webhook_secret_vault_id into app_record from public.app_installations i join public.partner_apps a on a.id=i.app_id where i.id=requested_installation_id and i.status='active';if app_record.app_id is null then raise exception 'Instalação inválida.';end if;select decrypted_secret into raw_secret from vault.decrypted_secrets where id=app_record.webhook_secret_vault_id;if raw_secret is null then raise exception 'Secret do app ausente.';end if;insert into public.webhook_endpoints(organization_id,name,url,secret_prefix,subscribed_events,environment)values(app_record.organization_id,'App · '||app_record.name,requested_url,left(raw_secret,12),array(select distinct unnest(requested_events||array['app.uninstalled'])),'production')returning id into endpoint;select vault.create_secret(raw_secret,'masterapp-app-endpoint-'||endpoint::text,'App installation webhook signing secret')into sid;update public.webhook_endpoints set vault_secret_id=sid where id=endpoint;insert into public.app_webhooks(app_id,installation_id,endpoint_id)values(app_record.app_id,requested_installation_id,endpoint);return endpoint;end$$;
create or replace function public.consume_app_rate_limit(requested_app_id uuid,requested_installation_id uuid,requested_organization_id uuid,requested_limit integer default 120) returns jsonb language plpgsql security definer set search_path='' as $$declare bucket timestamptz:=date_trunc('minute',clock_timestamp());used integer;lim integer:=least(greatest(coalesce(requested_limit,120),10),3000);begin if current_setting('request.jwt.claim.role',true)<>'service_role' then raise exception 'Operação interna.';end if;insert into public.app_rate_limit_buckets(app_id,installation_id,organization_id,bucket_start,request_count)values(requested_app_id,requested_installation_id,requested_organization_id,bucket,1)on conflict(app_id,installation_id,organization_id,bucket_start)do update set request_count=public.app_rate_limit_buckets.request_count+1 returning request_count into used;return jsonb_build_object('allowed',used<=lim,'limit',lim,'remaining',greatest(lim-used,0),'reset_at',extract(epoch from bucket+interval'1 minute')::bigint);end$$;
revoke all on function public.set_app_installation_config(uuid,text),public.set_partner_app_webhook_secret(uuid,text),public.create_app_installation_webhook(uuid,text,text[]),public.consume_app_rate_limit(uuid,uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.set_app_installation_config(uuid,text),public.set_partner_app_webhook_secret(uuid,text),public.create_app_installation_webhook(uuid,text,text[]),public.consume_app_rate_limit(uuid,uuid,uuid,integer) to service_role;

alter table public.partner_accounts enable row level security;alter table public.app_categories enable row level security;alter table public.partner_apps enable row level security;alter table public.app_versions enable row level security;alter table public.app_scopes enable row level security;alter table public.app_installations enable row level security;alter table public.app_installation_stores enable row level security;alter table public.app_pricing enable row level security;alter table public.app_oauth_authorizations enable row level security;alter table public.app_oauth_tokens enable row level security;alter table public.app_rate_limit_buckets enable row level security;alter table public.app_webhooks enable row level security;alter table public.app_reviews enable row level security;alter table public.app_review_reports enable row level security;alter table public.app_security_incidents enable row level security;alter table public.app_audit_logs enable row level security;

create policy partner_accounts_owner_read on public.partner_accounts for select to authenticated using(user_id=(select auth.uid()) or private.is_superadmin());
create policy app_categories_read on public.app_categories for select to authenticated using(active or private.is_superadmin());
create policy partner_apps_owner_or_marketplace on public.partner_apps for select to authenticated using(private.partner_owner(partner_id) or private.is_superadmin() or(status='published'and visibility in('public','unlisted'))or(status='published'and visibility='private'and private.integration_org_admin(private_organization_id)));
create policy app_versions_owner_or_published on public.app_versions for select to authenticated using(exists(select 1 from public.partner_apps a where a.id=app_id and(private.partner_owner(a.partner_id)or private.is_superadmin()or(a.status='published'and status='published'))));
create policy app_scopes_read on public.app_scopes for select to authenticated using(active or private.is_superadmin());
create policy app_installations_org_read on public.app_installations for select to authenticated using(private.integration_org_admin(organization_id)or private.is_superadmin());
create policy app_installation_stores_org_read on public.app_installation_stores for select to authenticated using(exists(select 1 from public.app_installations i where i.id=installation_id and private.integration_org_admin(i.organization_id)));
create policy app_pricing_marketplace_read on public.app_pricing for select to authenticated using(active or private.is_superadmin());
create policy app_reviews_marketplace_read on public.app_reviews for select to authenticated using(status='published'or private.is_superadmin()or private.integration_org_admin(organization_id));
create policy app_audit_org_read on public.app_audit_logs for select to authenticated using((organization_id is not null and private.integration_org_admin(organization_id))or private.is_superadmin());
create policy partner_platform_superadmin_accounts on public.partner_accounts for all to authenticated using(private.is_superadmin())with check(private.is_superadmin());
create policy partner_platform_superadmin_apps on public.partner_apps for all to authenticated using(private.is_superadmin())with check(private.is_superadmin());
create policy partner_platform_superadmin_versions on public.app_versions for all to authenticated using(private.is_superadmin())with check(private.is_superadmin());
create policy partner_platform_superadmin_incidents on public.app_security_incidents for all to authenticated using(private.is_superadmin())with check(private.is_superadmin());
create policy partner_platform_superadmin_reports on public.app_review_reports for all to authenticated using(private.is_superadmin())with check(private.is_superadmin());

revoke all on public.partner_accounts,public.app_categories,public.partner_apps,public.app_versions,public.app_scopes,public.app_installations,public.app_installation_stores,public.app_pricing,public.app_oauth_authorizations,public.app_oauth_tokens,public.app_rate_limit_buckets,public.app_webhooks,public.app_reviews,public.app_review_reports,public.app_security_incidents,public.app_audit_logs from public,anon,authenticated;
grant select on public.partner_accounts,public.app_categories,public.partner_apps,public.app_versions,public.app_scopes,public.app_installations,public.app_installation_stores,public.app_pricing,public.app_reviews,public.app_audit_logs to authenticated;
grant select,insert,update,delete on public.app_security_incidents,public.app_review_reports to authenticated;

with ranked as(select id,row_number()over(order by sort_order,id)tier,count(*)over()total from public.plans where active)
update public.plans p set partner_platform_enabled=true,app_marketplace_enabled=true,oauth_apps_enabled=(r.tier>=least(2,r.total)),paid_apps_enabled=(r.tier=r.total),max_app_installations=case when r.tier=r.total then null when r.tier=1 then 3 else 10 end,updated_at=now()from ranked r where p.id=r.id;

select cron.schedule('partner-platform-token-cleanup','43 3 * * *',$$update public.app_oauth_tokens set status='expired' where status='active' and refresh_expires_at<now();delete from public.app_oauth_authorizations where expires_at<now()-interval'1 day';delete from public.app_rate_limit_buckets where bucket_start<now()-interval'2 days'$$)where not exists(select 1 from cron.job where jobname='partner-platform-token-cleanup');

commit;
